update public.article_cache set translation = '{"texts": ["Korea''s Prime Minister recently made congratulatory remarks about the success of the popular game ''Crimson Desert,'' which was developed by a Korean game company.", "Crimson Desert received a lot of attention from gamers after its release. In particular, it is receiving positive responses from overseas as well.", "The Prime Minister highly evaluated the development of Korea''s gaming industry. He said that Korean games are showing competitiveness in the global market.", "This statement is interpreted as meaning that the government considers the gaming industry important. It is expected to have a positive impact on Korea''s cultural content exports."], "sentences": [{"text": "한국의 총리가 최근 인기를 얻고 있는 게임 ''크림슨 데저트(Crimson Desert)''의 성공에 대해 축하 발언을 했습니다.", "translation": "South Korea''s prime minister made congratulatory remarks regarding the success of the game ''Crimson Desert,'' which has recently been gaining popularity.", "vocab": [{"ko": "인기를 얻다", "en": "to gain popularity"}, {"ko": "축하 발언", "en": "congratulatory remarks"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker indicating an ongoing action. Chain: 얻다 → 얻고 있다 (is gaining).", "example_in_sentence": "인기를 얻고 있는"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "present modifier before a noun. 얻고 있다 → 인기를 얻고 있는 게임 = \"a game that is gaining popularity\".", "example_in_sentence": "인기를 얻고 있는 게임"}, {"type": "grammar", "label": "~에 대해", "exp": "Postposition indicating target or scope of an action. Here marks what the remarks concern.", "example_in_sentence": "성공에 대해"}, {"type": "expression", "label": "축하 발언을 하다", "exp": "Collocation meaning ''to make congratulatory remarks.'' 발언 (remarks/statement) + 하다 (do).", "example_in_sentence": "축하 발언을 했습니다"}]}, {"text": "이 게임은 한국 게임 회사에서 개발한 작품입니다.", "translation": "This game is a work developed by a Korean game company.", "vocab": [{"ko": "개발하다", "en": "to develop"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "describes a noun with a past action. 개발하다 → 개발한 작품 = \"a work that (they) developed\".", "example_in_sentence": "개발한 작품"}]}, {"text": "크림슨 데저트는 출시 후 많은 게이머들의 관심을 받았습니다.", "translation": "Crimson Desert received much attention from many gamers after its release.", "vocab": [{"ko": "출시", "en": "release; launch"}, {"ko": "관심을 받다", "en": "to receive attention"}], "analysis": [{"type": "grammar", "label": "~후", "exp": "Postposition meaning ''after.'' Marks temporal sequence. 출시 (release/launch) + 후 (after).", "example_in_sentence": "출시 후"}, {"type": "expression", "label": "관심을 받다", "exp": "Collocation meaning ''to receive/attract attention.'' Passive-sense expression with 받다 (receive).", "example_in_sentence": "관심을 받았습니다"}]}, {"text": "특히 해외에서도 좋은 반응을 얻고 있어요.", "translation": "In particular, it is gaining positive reactions from overseas as well.", "vocab": [{"ko": "해외", "en": "overseas/abroad"}], "analysis": [{"type": "grammar", "label": "~에서도", "exp": "Postposition ~에서 (from/in) + additive particle ~도 (also/even). Indicates scope expansion.", "example_in_sentence": "해외에서도"}, {"type": "grammar", "label": "~고 있다 (be V-ing)", "exp": "ongoing action. 얻다 → 얻고 있어요 = \"is gaining\".", "example_in_sentence": "얻고 있어요"}]}, {"text": "총리는 한국 게임 산업의 발전을 높이 평가했습니다.", "translation": "The prime minister praised the development of the Korean game industry.", "vocab": [{"ko": "발전", "en": "development/progress"}, {"ko": "높이 평가하다", "en": "to highly evaluate/appreciate"}], "analysis": [{"type": "expression", "label": "높이 평가하다", "exp": "Collocation meaning ''to highly evaluate/appreciate.'' 높이 (highly) is adverbial modifier + 평가하다 (evaluate).", "example_in_sentence": "높이 평가했습니다"}]}, {"text": "한국 게임이 세계 시장에서 경쟁력을 보여주고 있다고 말했어요.", "translation": "He said that Korean games are demonstrating competitiveness in the global market.", "vocab": [{"ko": "경쟁력", "en": "competitiveness"}, {"ko": "보여주다", "en": "to show/demonstrate"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect indicating ongoing action. Chain: 보여주다 → 보여주고 있다 (are demonstrating).", "example_in_sentence": "보여주고 있다"}, {"type": "grammar", "label": "~다고 말하다", "exp": "Reported speech marker ~다고 (that) + 말하다 (say). Quotes indirect speech with ~다고.", "example_in_sentence": "보여주고 있다고 말했어요"}]}, {"text": "이번 발언은 정부가 게임 산업을 중요하게 생각한다는 의미로 해석됩니다.", "translation": "This statement is interpreted to mean that the government considers the game industry important.", "vocab": [{"ko": "해석되다", "en": "to be interpreted"}], "analysis": [{"type": "grammar", "label": "~ㄴ/는다는 + N (that ~)", "exp": "links a statement to a noun. 생각한다 → 생각한다는 의미 = \"the meaning that (it) considers\".", "example_in_sentence": "생각한다는 의미"}]}, {"text": "한국의 문화 콘텐츠 수출에도 긍정적인 영향을 줄 것으로 예상돼요.", "translation": "It is anticipated that it will also have a positive impact on Korea''s cultural content exports.", "vocab": [{"ko": "문화 콘텐츠", "en": "cultural content"}, {"ko": "수출", "en": "export"}, {"ko": "예상되다", "en": "to be anticipated/expected"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것으로 예상되다 (is expected to)", "exp": "news phrase for predictions. 주다 → 줄 것으로 예상돼요 = \"is expected to give\".", "example_in_sentence": "줄 것으로 예상돼요"}, {"type": "expression", "label": "영향을 주다", "exp": "Collocation meaning ''to have/exert an impact.'' 영향 (impact) + 주다 (give).", "example_in_sentence": "영향을 줄"}]}], "version": "s6"}', vocab = '[{"ko": "인기를 얻다", "en": "to gain popularity", "note": ""}, {"ko": "축하 발언", "en": "congratulatory remarks", "note": ""}, {"ko": "개발하다", "en": "to develop", "note": ""}, {"ko": "출시", "en": "release; launch", "note": ""}, {"ko": "관심을 받다", "en": "to receive attention", "note": ""}, {"ko": "해외", "en": "overseas/abroad", "note": ""}, {"ko": "발전", "en": "development/progress", "note": ""}, {"ko": "높이 평가하다", "en": "to highly evaluate/appreciate", "note": ""}, {"ko": "경쟁력", "en": "competitiveness", "note": ""}, {"ko": "보여주다", "e