update public.article_cache set translation = '{"texts": ["The United States Central Intelligence Agency (CIA) conducted secret experiments on Korean prisoners of war during the Korean War. This fact has been revealed through recently declassified documents.", "According to the documents, the CIA conducted initial experiments of a highly classified project called ''MK-ULTRA'' on Korean prisoners of war. This project was carried out for the purpose of researching mind control and brainwashing techniques.", "The experiments at the time appear to have been conducted forcibly without the consent of the prisoners. The Korean government has not yet issued an official statement on this matter.", "With the release of these documents, controversy over unethical human experiments by the United States is expected to resurface. Analysis suggests this could also impact U.S.-Korea relations."], "sentences": [{"text": "미국 중앙정보국(CIA)이 한국전쟁 당시 한국인 포로들을 대상으로 비밀 실험을 했다는 사실이 공개됐어요.", "translation": "It has been revealed that the U.S. Central Intelligence Agency (CIA) conducted secret experiments on Korean prisoners of war during the Korean War.", "vocab": [{"ko": "중앙정보국", "en": "Central Intelligence Agency"}, {"ko": "포로", "en": "prisoner of war"}, {"ko": "대상", "en": "target; subject"}, {"ko": "공개되다", "en": "to be revealed; made public"}], "analysis": [{"type": "grammar", "label": "~다는 사실 (the fact that)", "exp": "turns a statement into \"the fact that ~\". 했다 → 했다는 사실 = \"the fact that (it) did\".", "example_in_sentence": "했다는 사실이"}, {"type": "expression", "label": "~을/를 대상으로 (targeting, on)", "exp": "names who an action is aimed at. 포로들 → 포로들을 대상으로 = \"on prisoners of war\".", "example_in_sentence": "포로들을 대상으로"}]}, {"text": "최근 기밀해제된 문서를 통해 확인된 내용입니다.", "translation": "It is content confirmed through recently declassified documents.", "vocab": [{"ko": "기밀해제되다", "en": "to be declassified"}, {"ko": "문서", "en": "document"}, {"ko": "확인되다", "en": "to be confirmed"}], "analysis": [{"type": "expression", "label": "~을/를 통해 (through)", "exp": "the means or channel. 문서 → 문서를 통해 = \"through documents\".", "example_in_sentence": "문서를 통해"}]}, {"text": "문서에 따르면 CIA는 ''MK-ULTRA''라는 극비 프로젝트의 초기 실험을 한국인 포로들에게 실시했어요.", "translation": "According to the documents, the CIA conducted initial experiments of a highly classified project called ''MK-ULTRA'' on Korean prisoners of war.", "vocab": [{"ko": "따르다", "en": "to follow; to go by"}, {"ko": "극비", "en": "highly secret; top secret"}, {"ko": "초기", "en": "initial; early"}, {"ko": "실시하다", "en": "to conduct; to implement"}], "analysis": [{"type": "expression", "label": "~에 따르면 (according to)", "exp": "gives the source of information. 문서 → 문서에 따르면 = \"according to the documents\".", "example_in_sentence": "문서에 따르면"}, {"type": "grammar", "label": "~(이)라는 (called)", "exp": "links a name to a noun. ''MK-ULTRA''라는 프로젝트 = \"a project called MK-ULTRA\".", "example_in_sentence": "''MK-ULTRA''라는"}, {"type": "expression", "label": "~에게 실시하다 (carry out on)", "exp": "실시하다 = to carry out; 에게 marks who it is done to. 포로들에게 실시했어요 = \"carried out on the prisoners\".", "example_in_sentence": "포로들에게 실시했어요"}]}, {"text": "이 프로젝트는 정신 조작과 세뇌 기술을 연구하는 목적으로 진행됐습니다.", "translation": "This project was carried out for the purpose of researching mind-control and brainwashing techniques.", "vocab": [{"ko": "정신", "en": "mind; spirit"}, {"ko": "조작", "en": "manipulation; operation"}, {"ko": "세뇌", "en": "brainwashing"}, {"ko": "기술", "en": "technique; technology"}], "analysis": [{"type": "expression", "label": "~(으)로 진행되다 (be carried out for/as)", "exp": "formal phrase for how or why something was carried out. 목적 → 목적으로 진행됐습니다 = \"was carried out for the purpose (of)\".", "example_in_sentence": "목적으로 진행됐습니다"}]}, {"text": "당시 실험은 포로들의 동의 없이 강제로 이뤄진 것으로 보여요.", "translation": "It appears that the experiments at that time were conducted forcibly without the prisoners'' consent.", "vocab": [{"ko": "당시", "en": "at that time; then"}, {"ko": "동의", "en": "consent; agreement"}, {"ko": "강제로", "en": "by force; forcibly"}, {"ko": "이루어지다", "en": "to be conducted; to take place"}], "analysis": [{"type": "grammar", "label": "~ 없이 (without)", "exp": "without something. 동의 → 동의 없이 = \"without consent\".", "example_in_sentence": "동의 없이"}, {"type": "grammar", "label": "~(으)ㄴ 것으로 보이다 (it appears that)", "exp": "a cautious conclusion in news. 이뤄지다 → 이뤄진 것으로 보여요 = \"it appears (they) were carried out\".", "example_in_sentence": "이뤄진 것으로 보여요"}]}, {"text": "한국 정부는 이에 대한 공식 입장을 아직 발표하지 않았습니다.", "translation": "The Korean government has not yet issued an official position on this.", "vocab": [{"ko": "정부", "en": "government"}, {"ko": "입장", "en": "position; stance"}, {"ko": "발표하다", "en": "to announce; to issue"}, {"ko": "아직", "en": "yet; still"}], "analysis": [{"type": "expression", "label": "~에 대한 (about, regarding)", "exp": "links a topic to a noun. 이 → 이에 대한 입장 = \"a position on this\".", "example_in_sentence": "이에 대한"}]}, {"text": "이번 문서 공개로 미국의 비윤리적인 인체 실험에 대한 논란이 다시 불거질 전망이에요.", "translation": "With this document release, controversy over the U.S.''s unethical human experiments is expected to resurface.", "vocab": [{"ko": "공개", "en": "disclosure; release"}, {"ko": "비윤리적", "en": "unethical"}, {"ko": "인체", "en": "human body"}, {"ko": "논란", "en": "controversy; debate"}], "analysis": [{"type": "grammar", "label": "~(으)로 (due to, with)", "exp": "cause. 문서 공개 → 문서 공개로 = \"with the release of the documents\".", "example_in_sentence": "공개로"}, {"type": "grammar", "label": "~(으)ㄹ 전망이다 (is expected to)", "exp": "news phrase for forecasts. 불거지다 → 불거질 전망이에요 = \"is expected to flare up\".", "example_in_sentence": "불거질 전망이에요"}, {"type": "expression", "label": "논란이 불거지다", "exp": "Collocation meaning ''controversy arises/surfaces''; 불거지다 = to come to the surface; to flare up.", "example_in_sentence": "논란이 다시 불거질"}]}, {"text": "한미 관계에도 영향을 미칠 수 있다는 분석이 나오고 있습니다.", "translation": "Analysis is emerging that it could also affect South Korea–U.S. relations.", "vocab": [{"ko": "관계", "en": "relations; relationship"}, {"ko": "영향", "en": "influence; impact"}, {"ko": "분석", "en": "analysis"}, {"ko": "나오다", "en": "to emerge; to come out"}], "analysis": [{"type": "expression", "label": "영향을 미치다 (affect)", "exp": "formal \"to have an influence on\". 영향을 미칠 수 있다 = \"could affect\".", "example_in_sentence": "영향을 미칠"}]}], "version": "s6"}', vocab = '[{"ko": "중앙정보국", "en": "Central Intelligence Agency", "note": ""}, {"ko": "포로", "en": "prisoner of war", "note": ""}, {"ko": "대상", "en": "target; subject", "note": ""}, {"ko": "공개되다", "en": "to be revealed; made public", "note": ""}, {"ko": "기밀해제되다", "en": "to be declassified", "note": ""}, {"ko": "문서", "en": "document", "note": ""}, {"ko": "확인되다", "en": "to be confirmed", "note": ""}, {"ko": "따르다", "en": "to follow; to go by", "note": ""}, {"ko": "극비", "en": "highly secret; top secret", "note": ""}, {"ko": "초기", "en": "initial; early", "note": ""}, {"ko": "실시하다", "en": "to conduct; to implement", "note": ""}, {"ko": "정신", "en": "mind; spirit", "note": ""}, {"ko": "조작", "en": "manipulation; operation", "note": ""}, {"ko": "세뇌", "en": "brainwashing", "note": ""}, {"ko": "기술", "en": "technique; technology", "note": ""}, {"ko": "당시", "en": "at that time; then", "note": ""}, {"ko": "동의", "en": "consent; agreement", "note": ""}, {"ko": "강제로", "en": "by force; forcibly", "note": ""}, {"ko": "이루어지다", "en": "to be conducted; to take place", "note": ""}, {"ko": "정부", "en": "government", "note": ""}, {"ko": "입장", "en": "position; stance", "note": ""}, {"ko": "발표하다", "en": "to announce; to issue", "note": ""}, {"ko": "아직", "en": "yet; still", "note": ""}, {"ko": "공개", "en": "disclosure; release", "note": ""}, {"ko": "비윤리적", "en": "unethical", "note": ""}, {"ko": "인체", "en": "human body", "note": ""}, {"ko": "논란", "en": "controversy; debate", "note": ""}, {"ko": "관계", "en": "relations; relationship", "note": ""}, {"ko": "영향", "en": "influence; impact", "note": ""}, {"ko": "분석", "en": "analysis", "note": ""}, {"ko": "나오다", "en": "to emerge; to come out", "note": ""}, {"word": "비밀 실험", "reading": "bimil silhum", "meaning": "secret experiment; clandestine test", "context": "한국인 포로들을 대상으로 비밀 실험을 했다"}, {"word": "기밀해제", "reading": "gimil haeje", "meaning": "declassification; release of classified documents", "context": "최근 기밀해제된 문서를 통해 확인"}, {"word": "프로젝트", "reading": "peurojektu", "meaning": "project", "context": "극비 프로젝트의 초기 실험을 한국인 포로"}, {"word": "정신 조작", "reading": "jeongsin jojak", "meaning": "mind control; psychological manipulation", "context": "정신 조작과 세뇌 기술을 연구하는"}]', grammar = '{"patterns": [{"name": "~다는 사실 (the fact that)", "level": "Advanced", "exp": "turns a statement into \"the fact that ~\". 했다 → 했다는 사실 = \"the fact that (it) did\".", "ex_ko": "미국 중앙정보국(CIA)이 한국전쟁 당시 한국인 포로들을 대상으로 비밀 실험을 했다는 사실이 공개됐어요.", "ex_en": "It has been revealed that the U.S. Central Intelligence Agency (CIA) conducted secret experiments on Korean prisoners of war during the Korean War."}, {"name": "~(이)라는 (called)", "level": "Advanced", "exp": "links a name to a noun. ''MK-ULTRA''라는 프로젝트 = \"a project called MK-ULTRA\".", "ex_ko": "문서에 따르면 CIA는 ''MK-ULTRA''라는 극비 프로젝트의 초기 실험을 한국인 포로들에게 실시했어요.", "ex_en": "According to the documents, the CIA conducted initial experiments of a highly classified project called ''MK-ULTRA'' on Korean prisoners of war."}, {"name": "~ 없이 (without)", "level": "Advanced", "exp": "without something. 동의 → 동의 없이 = \"without consent\".", "ex_ko": "당시 실험은 포로들의 동의 없이 강제로 이뤄진 것으로 보여요.", "ex_en": "It appears that the experiments at that time were conducted forcibly without the prisoners'' consent."}, {"name": "~(으)ㄴ 것으로 보이다 (it appears that)", "level": "Advanced", "exp": "a cautious conclusion in news. 이뤄지다 → 이뤄진 것으로 보여요 = \"it appears (they) were carried out\".", "ex_ko": "당시 실험은 포로들의 동의 없이 강제로 이뤄진 것으로 보여요.", "ex_en": "It appears that the experiments at that time were conducted forcibly without the prisoners'' consent."}, {"name": "~(으)로 (due to, with)", "level": "Advanced", "exp": "cause. 문서 공개 → 문서 공개로 = \"with the release of the documents\".", "ex_ko": "이번 문서 공개로 미국의 비윤리적인 인체 실험에 대한 논란이 다시 불거질 전망이에요.", "ex_en": "With this document release, controversy over the U.S.''s unethical human experiments is expected to resurface."}, {"name": "~(으)ㄹ 전망이다 (is expected to)", "level": "Advanced", "exp": "news phrase for forecasts. 불거지다 → 불거질 전망이에요 = \"is expected to flare up\".", "ex_ko": "이번 문서 공개로 미국의 비윤리적인 인체 실험에 대한 논란이 다시 불거질 전망이에요.", "ex_en": "With this document release, controversy over the U.S.''s unethical human experiments is expected to resurface."}]}', updated_at = now() where article_id = 'mogem6ffzb0r' and md5(translation) = '91c989137adab5870e18193b90e1c09b';
update public.article_cache set translation = '{"texts": ["President Lee Jae-myung issued a statement on the 26th regarding the shooting incident involving U.S. President Donald Trump. President Lee strongly condemned the incident, saying \"political violence is a serious threat to democracy.\" President Lee said, \"I was relieved to hear that President Trump and those involved are safe.\" He also added, \"I extend deep condolences to the American people.\"\n\nThis incident occurred at an event attended by President Trump. President Lee emphasized that political violence cannot be justified under any circumstances.\n\nThe Korean government announced that it will continue its cooperative relationship with the United States going forward. Both countries reconfirmed the importance of sharing democratic values.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "이재명 대통령이 26일 미국 도널드 트럼프 대통령 관련 총격 사건에 대해 입장을 발표했어요.", "translation": "President Lee Jae-myung announced a position on the shooting incident involving US President Donald Trump on the 26th.", "vocab": [{"ko": "총격 사건", "en": "shooting incident"}, {"ko": "입장을 발표하다", "en": "to announce a position/statement"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker indicating a completed action. 발표하다 (announce) becomes 발표했어요 in past polite form.", "example_in_sentence": "발표했어요"}]}, {"text": "이 대통령은 \"정치적 폭력은 민주주의에 대한 심각한 위협\"이라고 강하게 규탄했습니다.", "translation": "The President strongly condemned it, saying \"political violence is a serious threat to democracy.\"", "vocab": [{"ko": "정치적 폭력", "en": "political violence"}, {"ko": "위협", "en": "threat"}, {"ko": "규탄하다", "en": "to condemn/denounce"}], "analysis": [{"type": "grammar", "label": "~(이)라고 규탄하다 (condemn, saying)", "exp": "quoted speech with a reporting verb. 위협이다 → 위협이라고 규탄했습니다 = \"condemned (it), calling it a threat\".", "example_in_sentence": "위협\"이라고 강하게 규탄했습니다"}, {"type": "grammar", "label": "~았/었습니다", "exp": "Past tense in formal register (~습니다 ending). 규탄하다 becomes 규탄했습니다.", "example_in_sentence": "규탄했습니다"}]}, {"text": "이 대통령은 \"트럼프 대통령과 관계자들이 안전하다는 소식을 듣고 안도했다\"고 말했어요.", "translation": "The President said, \"Upon hearing news that President Trump and those involved are safe, I felt relief.\"", "vocab": [{"ko": "관계자", "en": "person(s) involved"}, {"ko": "안도하다", "en": "to feel relieved"}, {"ko": "소식", "en": "news/information"}], "analysis": [{"type": "grammar", "label": "~다는 + N (the news that)", "exp": "links a statement to a noun. 안전하다 → 안전하다는 소식 = \"the news that (they) are safe\".", "example_in_sentence": "안전하다는 소식"}, {"type": "grammar", "label": "~고", "exp": "Connective ending joining two clauses sequentially. Shows temporal or causal progression: ''and then / after doing ~''.", "example_in_sentence": "듣고"}]}, {"text": "또한 \"미국 국민들에게 깊은 위로의 마음을 전한다\"고 덧붙였습니다.", "translation": "He also added, \"I extend my deepest sympathy to the American people.\"", "vocab": [{"ko": "위로", "en": "consolation/comfort"}, {"ko": "덧붙이다", "en": "to add (in addition)"}], "analysis": []}, {"text": "이번 사건은 트럼프 대통령이 참석한 행사에서 발생했어요.", "translation": "This incident occurred at an event President Trump attended.", "vocab": [{"ko": "참석하다", "en": "to attend"}, {"ko": "행사", "en": "event"}, {"ko": "발생하다", "en": "to occur/happen"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "describes a noun with a past action. 참석하다 → 참석한 행사 = \"an event (Trump) attended\".", "example_in_sentence": "참석한 행사"}, {"type": "expression", "label": "~에서 발생하다", "exp": "Locational expression marking where an incident takes place. ~에서 (at/in a location).", "example_in_sentence": "행사에서 발생했어요"}]}, {"text": "이 대통령은 어떤 이유로도 정치적 폭력은 정당화될 수 없다고 강조했습니다.", "translation": "The President emphasized that political violence cannot be justified under any circumstances.", "vocab": [{"ko": "이유", "en": "reason"}, {"ko": "정당화되다", "en": "to be justified"}, {"ko": "강조하다", "en": "to emphasize"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Focus particle adding emphasis or inclusive meaning (''even'', ''any''). 어떤 이유로도 = ''under any reason whatsoever''.", "example_in_sentence": "어떤 이유로도"}, {"type": "grammar", "label": "~(으)ㄹ 수 없다 (cannot)", "exp": "impossibility. 정당화되다 → 정당화될 수 없다 = \"cannot be justified\".", "example_in_sentence": "정당화될 수 없다"}]}, {"text": "한국 정부는 앞으로도 미국과의 협력 관계를 지속할 것이라고 밝혔어요.", "translation": "The Korean government stated that it will continue to maintain cooperative relations with the United States going forward.", "vocab": [{"ko": "협력 관계", "en": "cooperative relationship"}, {"ko": "지속하다", "en": "to continue/sustain"}, {"ko": "밝히다", "en": "to state/clarify"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것이다 (will)", "exp": "future or intention. 지속하다 → 지속할 것이다 = \"will continue\".", "example_in_sentence": "지속할 것이라고"}, {"type": "grammar", "label": "~과/와의", "exp": "Postposition marking ''with'' or ''of'' relation. 미국 (US) + 과의 (with, possessive form).", "example_in_sentence": "미국과의"}]}, {"text": "양국 간 민주주의 가치 공유의 중요성도 다시 한번 확인했습니다.", "translation": "The importance of sharing democratic values between the two nations was also confirmed once again.", "vocab": [{"ko": "양국", "en": "two countries"}, {"ko": "민주주의 가치", "en": "democratic values"}, {"ko": "공유", "en": "sharing"}, {"ko": "중요성", "en": "importance"}], "analysis": [{"type": "grammar", "label": "~간", "exp": "Suffix marking relation ''between'' multiple entities. 양국 (two countries) + 간 (between/among).", "example_in_sentence": "양국 간"}, {"type": "expression", "label": "다시 한번", "exp": "Adverbial phrase meaning ''once again'' or ''one more time''. Emphasizes repetition or reiteration.", "example_in_sentence": "다시 한번"}]}], "version": "s6"}', vocab = '[{"ko": "총격 사건", "en": "shooting incident", "note": ""}, {"ko": "입장을 발표하다", "en": "to announce a position/statement", "note": ""}, {"ko": "정치적 폭력", "en": "political violence", "note": ""}, {"ko": "위협", "en": "threat", "note": ""}, {"ko": "규탄하다", "en": "to condemn/denounce", "note": ""}, {"ko": "관계자", "en": "person(s) involved", "note": ""}, {"ko": "안도하다", "en": "to feel relieved", "note": ""}, {"ko": "소식", "en": "news/information", "note": ""}, {"ko": "위로", "en": "consolation/comfort", "note": ""}, {"ko": "덧붙이다", "en": "to add (in addition)", "note": ""}, {"ko": "참석하다", "en": "to attend", "note": ""}, {"ko": "행사", "en": "event", "note": ""}, {"ko": "발생하다", "en": "to occur/happen", "note": ""}, {"ko": "이유", "en": "reason", "note": ""}, {"ko": "정당화되다", "en": "to be justified", "note": ""}, {"ko": "강조하다", "en": "to emphasize", "note": ""}, {"ko": "협력 관계", "en": "cooperative relationship", "note": ""}, {"ko": "지속하다", "en": "to continue/sustain", "note": ""}, {"ko": "밝히다", "en": "to state/clarify", "note": ""}, {"ko": "양국", "en": "two countries", "note": ""}, {"ko": "민주주의 가치", "en": "democratic values", "note": ""}, {"ko": "공유", "en": "sharing", "note": ""}, {"ko": "중요성", "en": "importance", "note": ""}, {"word": "폭력", "reading": "pokryok", "meaning": "violence", "context": "정치적 폭력은 민주주의에 대한"}, {"word": "협력", "reading": "hyeomnyok", "meaning": "cooperation; collaboration", "context": "미국과의 협력 관계를 지속할"}, {"word": "가치", "reading": "gachi", "meaning": "value; worth", "context": "민주주의 가치 공유의 중요성"}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Intermediate", "exp": "Past tense marker indicating a completed action. 발표하다 (announce) becomes 발표했어요 in past polite form.", "ex_ko": "이재명 대통령이 26일 미국 도널드 트럼프 대통령 관련 총격 사건에 대해 입장을 발표했어요.", "ex_en": "President Lee Jae-myung announced a position on the shooting incident involving US President Donald Trump on the 26th."}, {"name": "~(이)라고 규탄하다 (condemn, saying)", "level": "Intermediate", "exp": "quoted speech with a reporting verb. 위협이다 → 위협이라고 규탄했습니다 = \"condemned (it), calling it a threat\".", "ex_ko": "이 대통령은 \"정치적 폭력은 민주주의에 대한 심각한 위협\"이라고 강하게 규탄했습니다.", "ex_en": "The President strongly condemned it, saying \"political violence is a serious threat to democracy.\""}, {"name": "~았/었습니다", "level": "Intermediate", "exp": "Past tense in formal register (~습니다 ending). 규탄하다 becomes 규탄했습니다.", "ex_ko": "이 대통령은 \"정치적 폭력은 민주주의에 대한 심각한 위협\"이라고 강하게 규탄했습니다.", "ex_en": "The President strongly condemned it, saying \"political violence is a serious threat to democracy.\""}, {"name": "~다는 + N (the news that)", "level": "Intermediate", "exp": "links a statement to a noun. 안전하다 → 안전하다는 소식 = \"the news that (they) are safe\".", "ex_ko": "이 대통령은 \"트럼프 대통령과 관계자들이 안전하다는 소식을 듣고 안도했다\"고 말했어요.", "ex_en": "The President said, \"Upon hearing news that President Trump and those involved are safe, I felt relief.\""}, {"name": "~고", "level": "Intermediate", "exp": "Connective ending joining two clauses sequentially. Shows temporal or causal progression: ''and then / after doing ~''.", "ex_ko": "이 대통령은 \"트럼프 대통령과 관계자들이 안전하다는 소식을 듣고 안도했다\"고 말했어요.", "ex_en": "The President said, \"Upon hearing news that President Trump and those involved are safe, I felt relief.\""}, {"name": "~(으)ㄴ (past verb modifier)", "level": "Intermediate", "exp": "describes a noun with a past action. 참석하다 → 참석한 행사 = \"an event (Trump) attended\".", "ex_ko": "이번 사건은 트럼프 대통령이 참석한 행사에서 발생했어요.", "ex_en": "This incident occurred at an event President Trump attended."}, {"name": "~도", "level": "Intermediate", "exp": "Focus particle adding emphasis or inclusive meaning (''even'', ''any''). 어떤 이유로도 = ''under any reason whatsoever''.", "ex_ko": "이 대통령은 어떤 이유로도 정치적 폭력은 정당화될 수 없다고 강조했습니다.", "ex_en": "The President emphasized that political violence cannot be justified under any circumstances."}, {"name": "~(으)ㄹ 수 없다 (cannot)", "level": "Intermediate", "exp": "impossibility. 정당화되다 → 정당화될 수 없다 = \"cannot be justified\".", "ex_ko": "이 대통령은 어떤 이유로도 정치적 폭력은 정당화될 수 없다고 강조했습니다.", "ex_en": "The President emphasized that political violence cannot be justified under any circumstances."}, {"name": "~(으)ㄹ 것이다 (will)", "level": "Intermediate", "exp": "future or intention. 지속하다 → 지속할 것이다 = \"will continue\".", "ex_ko": "한국 정부는 앞으로도 미국과의 협력 관계를 지속할 것이라고 밝혔어요.", "ex_en": "The Korean government stated that it will continue to maintain cooperative relations with the United States going forward."}, {"name": "~과/와의", "level": "Intermediate", "exp": "Postposition marking ''with'' or ''of'' relation. 미국 (US) + 과의 (with, possessive form).", "ex_ko": "한국 정부는 앞으로도 미국과의 협력 관계를 지속할 것이라고 밝혔어요.", "ex_en": "The Korean government stated that it will continue to maintain cooperative relations with the United States going forward."}, {"name": "~간", "level": "Intermediate", "exp": "Suffix marking relation ''between'' multiple entities. 양국 (two countries) + 간 (between/among).", "ex_ko": "양국 간 민주주의 가치 공유의 중요성도 다시 한번 확인했습니다.", "ex_en": "The importance of sharing democratic values between the two nations was also confirmed once again."}]}', updated_at = now() where article_id = 'mogemybt3ckl' and md5(translation) = 'f9ad40158c0f3ef952ea55e2f6433c49';
update public.article_cache set translation = '{"texts": ["Something interesting happened in a country called Zimbabwe. A hungry crocodile came into a hotel.", "The crocodile went up to the hotel kitchen. It seems it came looking for food. People were very surprised.", "Hotel staff safely removed the crocodile. Fortunately, no one was injured.", "In Africa, things like this happen sometimes. Animals come to places where people live. It''s really an interesting occurrence."], "sentences": [{"text": "짐바브웨라는 나라에서 신기한 일이 일어났어요.", "translation": "In a country called Zimbabwe, something interesting happened.", "vocab": [{"ko": "짐바브웨", "en": "Zimbabwe"}, {"ko": "신기하다", "en": "to be interesting; to be curious"}, {"ko": "일어나다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~(이)라는 (called)", "exp": "links a name to a noun. 짐바브웨 → 짐바브웨라는 나라 = \"a country called Zimbabwe\".", "example_in_sentence": "짐바브웨라는 나라"}, {"type": "grammar", "label": "~에서", "exp": "Locative particle marking the place where an action occurs.", "example_in_sentence": "나라에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for completed action. 일어나다 (arise) → 일어났어요 (happened).", "example_in_sentence": "일어났어요"}]}, {"text": "배고픈 악어 한 마리가 호텔로 들어왔어요.", "translation": "One hungry crocodile entered the hotel.", "vocab": [{"ko": "배고프다", "en": "to be hungry"}, {"ko": "악어", "en": "crocodile"}, {"ko": "마리", "en": "counter for animals"}, {"ko": "들어오다", "en": "to enter; to come in"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "adjective before a noun. 배고프다 → 배고픈 악어 = \"a hungry crocodile\".", "example_in_sentence": "배고픈"}, {"type": "grammar", "label": "~로", "exp": "Directional particle marking destination. Indicates movement toward the hotel.", "example_in_sentence": "호텔로"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 들어오다 (enter) → 들어왔어요 (entered).", "example_in_sentence": "들어왔어요"}]}, {"text": "악어는 호텔 부엌까지 올라왔어요.", "translation": "The crocodile came up all the way to the hotel kitchen.", "vocab": [{"ko": "부엌", "en": "kitchen"}, {"ko": "올라오다", "en": "to come up; to climb up"}], "analysis": [{"type": "grammar", "label": "~까지", "exp": "Particle indicating extent or limit; ''up to; as far as; all the way to''.", "example_in_sentence": "부엌까지"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 올라오다 (climb up) → 올라왔어요 (came up).", "example_in_sentence": "올라왔어요"}]}, {"text": "음식을 찾아서 온 것 같아요.", "translation": "It seems to have come looking for food.", "vocab": [{"ko": "음식", "en": "food"}, {"ko": "찾다", "en": "to find; to look for"}], "analysis": [{"type": "grammar", "label": "~아/어서", "exp": "Conjunctive ending expressing reason or sequential action. 찾다 → 찾아서 (having searched/looking for).", "example_in_sentence": "찾아서"}, {"type": "grammar", "label": "~ㄴ/은 것 같다", "exp": "Expression of conjecture/supposition. Past participle + 것 + 같다 = ''seems to have (done)''.", "example_in_sentence": "온 것 같아요"}]}, {"text": "사람들이 깜짝 놀랐어요.", "translation": "People were startled.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "깜짝", "en": "suddenly; with a start"}, {"ko": "놀라다", "en": "to be surprised; to be startled"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 놀라다 (startle) → 놀랐어요 (were startled).", "example_in_sentence": "놀랐어요"}]}, {"text": "호텔 직원들이 악어를 안전하게 내보냈어요.", "translation": "Hotel staff safely let the crocodile out.", "vocab": [{"ko": "직원", "en": "staff; employee"}, {"ko": "안전하다", "en": "to be safe"}, {"ko": "내보내다", "en": "to let out; to send out"}], "analysis": [{"type": "grammar", "label": "~게 (adverb form)", "exp": "turns an adjective into an adverb. 안전하다 → 안전하게 = \"safely\".", "example_in_sentence": "안전하게"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 내보내다 (let out) → 내보냈어요 (let out).", "example_in_sentence": "내보냈어요"}]}, {"text": "다행히 다친 사람은 없었어요.", "translation": "Fortunately, there were no injured people.", "vocab": [{"ko": "다행히", "en": "fortunately; luckily"}, {"ko": "다치다", "en": "to be injured; to get hurt"}], "analysis": [{"type": "grammar", "label": "~ㄴ (attributive)", "exp": "Past participle of 다치다, modifying 사람. Expresses completed state.", "example_in_sentence": "다친"}, {"type": "grammar", "label": "~았/었어요 (past)", "exp": "past polite. 없다 → 없었어요 = \"there was not\".", "example_in_sentence": "없었어요"}]}, {"text": "아프리카에서는 이런 일이 가끔 있어요.", "translation": "In Africa, such things happen sometimes.", "vocab": [{"ko": "아프리카", "en": "Africa"}, {"ko": "이런", "en": "such; this kind of"}, {"ko": "가끔", "en": "sometimes; occasionally"}], "analysis": [{"type": "grammar", "label": "~에서는", "exp": "Locative particle + topic marker. 에서 (in/at) + 는 (as for) = ''in/at (place), (speaking of that place)''.", "example_in_sentence": "아프리카에서는"}, {"type": "grammar", "label": "~어요 (present)", "exp": "Present tense habitual ending. 있다 (happen/occur) → 있어요 (happen).", "example_in_sentence": "있어요"}]}, {"text": "동물들이 사람이 사는 곳에 와요.", "translation": "Animals come to places where people live.", "vocab": [{"ko": "동물", "en": "animal"}, {"ko": "사람", "en": "person; people"}, {"ko": "살다", "en": "to live; to reside"}, {"ko": "곳", "en": "place; spot"}], "analysis": [{"type": "grammar", "label": "~는 (attributive, present)", "exp": "Present participle form of 살다, modifying 곳. Creates relative clause ''places where (people) live''.", "example_in_sentence": "사는"}, {"type": "grammar", "label": "~에", "exp": "Locative/directional particle marking the destination of movement.", "example_in_sentence": "곳에"}, {"type": "grammar", "label": "~어요 (present)", "exp": "Present tense ending. 오다 (come) → 와요 (come).", "example_in_sentence": "와요"}]}, {"text": "정말 신기한 일이에요.", "translation": "It is truly an interesting thing.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "신기하다", "en": "to be interesting; to be curious"}], "analysis": [{"type": "grammar", "label": "~ㄴ (attributive)", "exp": "Attributive form of adjective 신기하다, modifying 일. Expresses quality/state.", "example_in_sentence": "신기한"}, {"type": "grammar", "label": "~이에요", "exp": "Present tense copula for nouns ending in consonant. 일 (thing) + 이에요 (is).", "example_in_sentence": "이에요"}]}], "version": "s6"}', vocab = '[{"ko": "짐바브웨", "en": "Zimbabwe", "note": ""}, {"ko": "신기하다", "en": "to be interesting; to be curious", "note": ""}, {"ko": "일어나다", "en": "to happen; to occur", "note": ""}, {"ko": "배고프다", "en": "to be hungry", "note": ""}, {"ko": "악어", "en": "crocodile", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "들어오다", "en": "to enter; to come in", "note": ""}, {"ko": "부엌", "en": "kitchen", "note": ""}, {"ko": "올라오다", "en": "to come up; to climb up", "note": ""}, {"ko": "음식", "en": "food", "note": ""}, {"ko": "찾다", "en": "to find; to look for", "note": ""}, {"ko": "사람", "en": "person; people", "note": ""}, {"ko": "깜짝", "en": "suddenly; with a start", "note": ""}, {"ko": "놀라다", "en": "to be surprised; to be startled", "note": ""}, {"ko": "직원", "en": "staff; employee", "note": ""}, {"ko": "안전하다", "en": "to be safe", "note": ""}, {"ko": "내보내다", "en": "to let out; to send out", "note": ""}, {"ko": "다행히", "en": "fortunately; luckily", "note": ""}, {"ko": "다치다", "en": "to be injured; to get hurt", "note": ""}, {"ko": "아프리카", "en": "Africa", "note": ""}, {"ko": "이런", "en": "such; this kind of", "note": ""}, {"ko": "가끔", "en": "sometimes; occasionally", "note": ""}, {"ko": "동물", "en": "animal", "note": ""}, {"ko": "살다", "en": "to live; to reside", "note": ""}, {"ko": "곳", "en": "place; spot", "note": ""}, {"ko": "정말", "en": "really; truly", "note": ""}, {"word": "호텔", "reading": "hotel", "meaning": "hotel", "context": "악어 한 마리가 호텔로 들어왔어요"}]', grammar = '{"patterns": [{"name": "~(이)라는 (called)", "level": "Starter", "exp": "links a name to a noun. 짐바브웨 → 짐바브웨라는 나라 = \"a country called Zimbabwe\".", "ex_ko": "짐바브웨라는 나라에서 신기한 일이 일어났어요.", "ex_en": "In a country called Zimbabwe, something interesting happened."}, {"name": "~에서", "level": "Starter", "exp": "Locative/directional particle marking the destination of movement.", "ex_ko": "짐바브웨라는 나라에서 신기한 일이 일어났어요.", "ex_en": "In a country called Zimbabwe, something interesting happened."}, {"name": "~았/었어요 (past)", "level": "Starter", "exp": "Past tense ending for completed action. 일어나다 (arise) → 일어났어요 (happened).", "ex_ko": "짐바브웨라는 나라에서 신기한 일이 일어났어요.", "ex_en": "In a country called Zimbabwe, something interesting happened."}, {"name": "~(으)ㄴ (adjective modifier)", "level": "Starter", "exp": "adjective before a noun. 배고프다 → 배고픈 악어 = \"a hungry crocodile\".", "ex_ko": "배고픈 악어 한 마리가 호텔로 들어왔어요.", "ex_en": "One hungry crocodile entered the hotel."}, {"name": "~로", "level": "Starter", "exp": "Directional particle marking destination. Indicates movement toward the hotel.", "ex_ko": "배고픈 악어 한 마리가 호텔로 들어왔어요.", "ex_en": "One hungry crocodile entered the hotel."}, {"name": "~까지", "level": "Starter", "exp": "Particle indicating extent or limit; ''up to; as far as; all the way to''.", "ex_ko": "악어는 호텔 부엌까지 올라왔어요.", "ex_en": "The crocodile came up all the way to the hotel kitchen."}, {"name": "~아/어서", "level": "Starter", "exp": "Conjunctive ending expressing reason or sequential action. 찾다 → 찾아서 (having searched/looking for).", "ex_ko": "음식을 찾아서 온 것 같아요.", "ex_en": "It seems to have come looking for food."}, {"name": "~ㄴ/은 것 같다", "level": "Starter", "exp": "Expression of conjecture/supposition. Past participle + 것 + 같다 = ''seems to have (done)''.", "ex_ko": "음식을 찾아서 온 것 같아요.", "ex_en": "It seems to have come looking for food."}, {"name": "~게 (adverb form)", "level": "Starter", "exp": "turns an adjective into an adverb. 안전하다 → 안전하게 = \"safely\".", "ex_ko": "호텔 직원들이 악어를 안전하게 내보냈어요.", "ex_en": "Hotel staff safely let the crocodile out."}, {"name": "~ㄴ (attributive)", "level": "Starter", "exp": "Attributive form of adjective 신기하다, modifying 일. Expresses quality/state.", "ex_ko": "다행히 다친 사람은 없었어요.", "ex_en": "Fortunately, there were no injured people."}, {"name": "~에서는", "level": "Starter", "exp": "Locative particle + topic marker. 에서 (in/at) + 는 (as for) = ''in/at (place), (speaking of that place)''.", "ex_ko": "아프리카에서는 이런 일이 가끔 있어요.", "ex_en": "In Africa, such things happen sometimes."}, {"name": "~어요 (present)", "level": "Starter", "exp": "Present tense habitual ending. 있다 (happen/occur) → 있어요 (happen).", "ex_ko": "아프리카에서는 이런 일이 가끔 있어요.", "ex_en": "In Africa, such things happen sometimes."}, {"name": "~는 (attributive, present)", "level": "Starter", "exp": "Present participle form of 살다, modifying 곳. Creates relative clause ''places where (people) live''.", "ex_ko": "동물들이 사람이 사는 곳에 와요.", "ex_en": "Animals come to places where people live."}, {"name": "~이에요", "level": "Starter", "exp": "Present tense copula for nouns ending in consonant. 일 (thing) + 이에요 (is).", "ex_ko": "정말 신기한 일이에요.", "ex_en": "It is truly an interesting thing."}]}', updated_at = now() where article_id = 'mogentjcwr78' and md5(translation) = '6358cb950902e68e87bca4b705830ccc';
update public.article_cache set translation = '{"texts": ["In 2013, NASA in the United States launched a lunar exploration rocket. However, an unexpected event occurred when the rocket was launched.", "A small frog near the rocket launch pad was blown into the sky by the rocket''s strong wind. This moment was captured directly by NASA''s camera.", "The frog was floating in the air along with the rocket smoke. This photograph became a big topic of discussion on the internet.", "Experts said that the frog was likely living in a pond near the launch pad. They explained that this happened because of the strong force of the rocket launch."], "sentences": [{"text": "2013년 미국 NASA에서 달 탐사 로켓을 발사했어요.", "translation": "In 2013, NASA in the United States launched a moon exploration rocket.", "vocab": [{"ko": "달 탐사", "en": "moon exploration"}, {"ko": "로켓", "en": "rocket"}, {"ko": "발사하다", "en": "to launch"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for narrative. 발사(하다) + 았 → 발사했어요 marks completed action in informal polite style.", "example_in_sentence": "발사했어요"}]}, {"text": "그런데 로켓이 발사될 때 예상하지 못한 일이 일어났습니다.", "translation": "However, an unexpected event occurred when the rocket was being launched.", "vocab": [{"ko": "예상하다", "en": "to anticipate; to expect"}, {"ko": "일어나다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때 (when)", "exp": "when something happens. 발사되다 → 발사될 때 = \"when (the rocket) was launched\".", "example_in_sentence": "발사될 때"}, {"type": "grammar", "label": "~지 못하다 (could not)", "exp": "inability. 예상하다 → 예상하지 못한 일 = \"something (no one) could foresee\".", "example_in_sentence": "예상하지 못한"}]}, {"text": "로켓 발사대 근처에 있던 작은 개구리가 로켓의 강한 바람에 하늘로 날아갔어요.", "translation": "A small frog that was near the launch pad was blown into the sky by the rocket''s strong blast.", "vocab": [{"ko": "발사대", "en": "launch pad"}, {"ko": "개구리", "en": "frog"}, {"ko": "바람", "en": "wind"}, {"ko": "날아가다", "en": "to fly away"}], "analysis": [{"type": "grammar", "label": "~던", "exp": "Past participle for incomplete/habitual state. 있다 + 던 → 있던 ''that was (in the state of being)'' modifies 개구리.", "example_in_sentence": "있던"}, {"type": "grammar", "label": "~에 (because of)", "exp": "cause, after a noun. 바람 → 강한 바람에 = \"because of the strong wind\".", "example_in_sentence": "바람에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 날아가다 + 았 → 날아갔어요 marks completed action.", "example_in_sentence": "날아갔어요"}]}, {"text": "이 순간이 NASA의 카메라에 그대로 찍혔습니다.", "translation": "This moment was captured on NASA''s camera just as it happened.", "vocab": [{"ko": "순간", "en": "moment; instant"}, {"ko": "그대로", "en": "exactly; as is"}, {"ko": "찍히다", "en": "to be captured; to be photographed"}], "analysis": [{"type": "grammar", "label": "~았/었습니다", "exp": "Past tense in formal/written style. 찍히다 + 었 → 찍혔습니다 marks completed passive action.", "example_in_sentence": "찍혔습니다"}]}, {"text": "개구리는 로켓 연기와 함께 공중에 떠 있는 모습이었어요.", "translation": "The frog could be seen floating in the air along with the rocket smoke.", "vocab": [{"ko": "연기", "en": "smoke"}, {"ko": "함께", "en": "together"}, {"ko": "공중", "en": "air; sky"}, {"ko": "뜨다", "en": "to float"}], "analysis": [{"type": "grammar", "label": "~와/과 함께", "exp": "Coordinating particle + adverbial noun = ''together with.'' 연기 + 와 + 함께 marks accompaniment.", "example_in_sentence": "연기와 함께"}, {"type": "grammar", "label": "~는 모습", "exp": "Present participle + noun ''appearance/sight.'' 떠 있다 + 는 → 떠 있는 모습 ''the sight of floating.''", "example_in_sentence": "떠 있는 모습"}]}, {"text": "이 사진은 인터넷에서 큰 화제가 되었습니다.", "translation": "This photograph became a major topic on the internet.", "vocab": [{"ko": "사진", "en": "photograph"}, {"ko": "인터넷", "en": "internet"}, {"ko": "화제", "en": "topic; subject of discussion"}], "analysis": [{"type": "expression", "label": "~이/가 화제가 되다", "exp": "Idiomatic expression ''to become a topic/subject of discussion.'' 화제 (topic) + 되다 (to become).", "example_in_sentence": "화제가 되었습니다"}]}, {"text": "전문가들은 개구리가 발사대 주변 연못에서 살고 있었을 것이라고 말했어요.", "translation": "Experts said that the frog was likely living in a pond near the launch pad.", "vocab": [{"ko": "전문가", "en": "expert"}, {"ko": "주변", "en": "vicinity; surrounding area"}, {"ko": "연못", "en": "pond"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~았/었을 것이다 (probably was)", "exp": "a guess about the past. 살고 있다 → 살고 있었을 것이다 = \"(it) was probably living\".", "example_in_sentence": "살고 있었을 것이라고"}, {"type": "grammar", "label": "~(이)라고 말하다 (said that)", "exp": "reported speech. 것이다 → 것이라고 말했어요 = \"said that (it) probably ~\".", "example_in_sentence": "것이라고 말했어요"}]}, {"text": "로켓 발사의 강한 힘 때문에 이런 일이 생겼다고 설명했습니다.", "translation": "They explained that this happened because of the rocket launch''s strong force.", "vocab": [{"ko": "발사", "en": "launch"}, {"ko": "힘", "en": "force; power"}, {"ko": "생기다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~ 때문에 (because of N)", "exp": "reason, after a noun. 힘 → 강한 힘 때문에 = \"because of the strong force\".", "example_in_sentence": "강한 힘 때문에"}, {"type": "grammar", "label": "~다고 설명하다 (explain that)", "exp": "reported speech. 생겼다 → 생겼다고 설명했습니다 = \"explained that (it) happened\".", "example_in_sentence": "생겼다고 설명했습니다"}]}], "version": "s6"}', vocab = '[{"ko": "달 탐사", "en": "moon exploration", "note": ""}, {"ko": "로켓", "en": "rocket", "note": ""}, {"ko": "발사하다", "en": "to launch", "note": ""}, {"ko": "예상하다", "en": "to anticipate; to expect", "note": ""}, {"ko": "일어나다", "en": "to happen; to occur", "note": ""}, {"ko": "발사대", "en": "launch pad", "note": ""}, {"ko": "개구리", "en": "frog", "note": ""}, {"ko": "바람", "en": "wind", "note": ""}, {"ko": "날아가다", "en": "to fly away", "note": ""}, {"ko": "순간", "en": "moment; instant", "note": ""}, {"ko": "그대로", "en": "exactly; as is", "note": ""}, {"ko": "찍히다", "en": "to be captured; to be photographed", "note": ""}, {"ko": "연기", "en": "smoke", "note": ""}, {"ko": "함께", "en": "together", "note": ""}, {"ko": "공중", "en": "air; sky", "note": ""}, {"ko": "뜨다", "en": "to float", "note": ""}, {"ko": "사진", "en": "photograph", "note": ""}, {"ko": "인터넷", "en": "internet", "note": ""}, {"ko": "화제", "en": "topic; subject of discussion", "note": ""}, {"ko": "전문가", "en": "expert", "note": ""}, {"ko": "주변", "en": "vicinity; surrounding area", "note": ""}, {"ko": "연못", "en": "pond", "note": ""}, {"ko": "살다", "en": "to live", "note": ""}, {"ko": "발사", "en": "launch", "note": ""}, {"ko": "힘", "en": "force; power", "note": ""}, {"ko": "생기다", "en": "to happen; to occur", "note": ""}, {"word": "탐사", "reading": "tamsа", "meaning": "exploration; investigation", "context": "달 탐사 로켓을 발사했어요"}]', grammar = '{"patterns": [{"name": "~았/었어요", "level": "Intermediate", "exp": "Past tense ending for narrative. 발사(하다) + 았 → 발사했어요 marks completed action in informal polite style.", "ex_ko": "2013년 미국 NASA에서 달 탐사 로켓을 발사했어요.", "ex_en": "In 2013, NASA in the United States launched a moon exploration rocket."}, {"name": "~(으)ㄹ 때 (when)", "level": "Intermediate", "exp": "when something happens. 발사되다 → 발사될 때 = \"when (the rocket) was launched\".", "ex_ko": "그런데 로켓이 발사될 때 예상하지 못한 일이 일어났습니다.", "ex_en": "However, an unexpected event occurred when the rocket was being launched."}, {"name": "~지 못하다 (could not)", "level": "Intermediate", "exp": "inability. 예상하다 → 예상하지 못한 일 = \"something (no one) could foresee\".", "ex_ko": "그런데 로켓이 발사될 때 예상하지 못한 일이 일어났습니다.", "ex_en": "However, an unexpected event occurred when the rocket was being launched."}, {"name": "~던", "level": "Intermediate", "exp": "Past participle for incomplete/habitual state. 있다 + 던 → 있던 ''that was (in the state of being)'' modifies 개구리.", "ex_ko": "로켓 발사대 근처에 있던 작은 개구리가 로켓의 강한 바람에 하늘로 날아갔어요.", "ex_en": "A small frog that was near the launch pad was blown into the sky by the rocket''s strong blast."}, {"name": "~에 (because of)", "level": "Intermediate", "exp": "cause, after a noun. 바람 → 강한 바람에 = \"because of the strong wind\".", "ex_ko": "로켓 발사대 근처에 있던 작은 개구리가 로켓의 강한 바람에 하늘로 날아갔어요.", "ex_en": "A small frog that was near the launch pad was blown into the sky by the rocket''s strong blast."}, {"name": "~았/었습니다", "level": "Intermediate", "exp": "Past tense in formal/written style. 찍히다 + 었 → 찍혔습니다 marks completed passive action.", "ex_ko": "이 순간이 NASA의 카메라에 그대로 찍혔습니다.", "ex_en": "This moment was captured on NASA''s camera just as it happened."}, {"name": "~와/과 함께", "level": "Intermediate", "exp": "Coordinating particle + adverbial noun = ''together with.'' 연기 + 와 + 함께 marks accompaniment.", "ex_ko": "개구리는 로켓 연기와 함께 공중에 떠 있는 모습이었어요.", "ex_en": "The frog could be seen floating in the air along with the rocket smoke."}, {"name": "~는 모습", "level": "Intermediate", "exp": "Present participle + noun ''appearance/sight.'' 떠 있다 + 는 → 떠 있는 모습 ''the sight of floating.''", "ex_ko": "개구리는 로켓 연기와 함께 공중에 떠 있는 모습이었어요.", "ex_en": "The frog could be seen floating in the air along with the rocket smoke."}, {"name": "~았/었을 것이다 (probably was)", "level": "Intermediate", "exp": "a guess about the past. 살고 있다 → 살고 있었을 것이다 = \"(it) was probably living\".", "ex_ko": "전문가들은 개구리가 발사대 주변 연못에서 살고 있었을 것이라고 말했어요.", "ex_en": "Experts said that the frog was likely living in a pond near the launch pad."}, {"name": "~(이)라고 말하다 (said that)", "level": "Intermediate", "exp": "reported speech. 것이다 → 것이라고 말했어요 = \"said that (it) probably ~\".", "ex_ko": "전문가들은 개구리가 발사대 주변 연못에서 살고 있었을 것이라고 말했어요.", "ex_en": "Experts said that the frog was likely living in a pond near the launch pad."}, {"name": "~ 때문에 (because of N)", "level": "Intermediate", "exp": "reason, after a noun. 힘 → 강한 힘 때문에 = \"because of the strong force\".", "ex_ko": "로켓 발사의 강한 힘 때문에 이런 일이 생겼다고 설명했습니다.", "ex_en": "They explained that this happened because of the rocket launch''s strong force."}, {"name": "~다고 설명하다 (explain that)", "level": "Intermediate", "exp": "reported speech. 생겼다 → 생겼다고 설명했습니다 = \"explained that (it) happened\".", "ex_ko": "로켓 발사의 강한 힘 때문에 이런 일이 생겼다고 설명했습니다.", "ex_en": "They explained that this happened because of the rocket launch''s strong force."}]}', updated_at = now() where article_id = 'mogeoe04bzt8' and md5(translation) = '51a9c446ceddb24bf52abdf1c0208a40';
update public.article_cache set translation = '{"texts": ["Korean Coast Guard rescue workers are receiving special training. They work to save people in the sea.", "There is a large swimming pool at the training facility. At this swimming pool, rescue workers undergo difficult tests. They train by creating situations similar to the actual sea.", "Rescue workers must safely save people who have fallen into the water. That''s why they practice hard every day. They build up their skills through difficult training.", "Thanks to this training, the coast guard can rescue many people in the sea. They are making Korea''s seas safer."], "sentences": [{"text": "한국 해양경찰의 구조 요원들이 특별한 훈련을 받고 있어요.", "translation": "South Korean coast guard rescue personnel are receiving special training.", "vocab": [{"ko": "해양경찰", "en": "coast guard"}, {"ko": "구조 요원", "en": "rescue personnel"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "훈련", "en": "training"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker indicating an ongoing action. 받다 (receive) → 받고 있어요 (are receiving).", "example_in_sentence": "받고 있어요"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object. 훈련 (training) is the object of the verb 받다 (receive).", "example_in_sentence": "훈련을"}]}, {"text": "이들은 바다에서 사람을 구하는 일을 해요.", "translation": "They do the work of rescuing people in the sea.", "vocab": [{"ko": "바다", "en": "sea"}, {"ko": "사람", "en": "person; people"}, {"ko": "구하다", "en": "to rescue; to save"}], "analysis": [{"type": "grammar", "label": "~는 일 (the work of V-ing)", "exp": "~는 describes 일 (work). 구하다 → 사람을 구하는 일 = \"the work of rescuing people\".", "example_in_sentence": "구하는 일"}, {"type": "grammar", "label": "~에서", "exp": "Locative particle indicating the location where an action takes place. 바다 (sea) is where the action occurs.", "example_in_sentence": "바다에서"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object. 사람 (people) is the object of 구하다 (rescue).", "example_in_sentence": "사람을"}]}, {"text": "훈련장에는 큰 수영장이 있어요.", "translation": "There is a large swimming pool at the training facility.", "vocab": [{"ko": "훈련장", "en": "training facility"}, {"ko": "크다", "en": "to be big; large"}, {"ko": "수영장", "en": "swimming pool"}], "analysis": [{"type": "grammar", "label": "~에는", "exp": "Topic-marking particle ~는 combined with locative ~에. Indicates location with topic emphasis (at the training facility, there is...).", "example_in_sentence": "훈련장에는"}, {"type": "grammar", "label": "~이/가 있다 (there is)", "exp": "says that something exists. 수영장 → 수영장이 있어요 = \"there is a swimming pool\".", "example_in_sentence": "수영장이 있어요"}]}, {"text": "이 수영장에서 구조 요원들은 어려운 테스트를 받아요.", "translation": "In this pool, the rescue workers take difficult tests.", "vocab": [{"ko": "어렵다", "en": "to be difficult"}, {"ko": "테스트", "en": "test"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle indicating location where an action takes place. 수영장 (swimming pool) is where the test occurs.", "example_in_sentence": "수영장에서"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object. 테스트 (test) is the object of 받다 (receive).", "example_in_sentence": "테스트를"}]}, {"text": "실제 바다와 비슷한 상황을 만들어서 훈련해요.", "translation": "They train by creating situations similar to the real sea.", "vocab": [{"ko": "실제", "en": "reality; actual"}, {"ko": "비슷하다", "en": "to be similar"}, {"ko": "상황", "en": "situation"}, {"ko": "만들다", "en": "to make; to create"}], "analysis": [{"type": "grammar", "label": "~와/과 비슷한 (similar to)", "exp": "comparison. 바다 → 바다와 비슷한 상황 = \"a situation similar to the sea\".", "example_in_sentence": "바다와 비슷한"}, {"type": "grammar", "label": "~아/어서 (and then)", "exp": "one action leads to the next. 만들다 → 만들어서 = \"make (situations) and then\".", "example_in_sentence": "만들어서"}]}, {"text": "구조 요원들은 물에 빠진 사람을 안전하게 구해야 해요.", "translation": "Rescue personnel must safely rescue people who have fallen into the water.", "vocab": [{"ko": "물", "en": "water"}, {"ko": "빠지다", "en": "to fall (into)"}, {"ko": "안전하다", "en": "to be safe"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "describes a noun with a past action. 빠지다 → 물에 빠진 사람 = \"a person who has fallen into the water\".", "example_in_sentence": "빠진 사람"}, {"type": "grammar", "label": "~아/어야 하다 (must)", "exp": "obligation. 구하다 → 구해야 해요 = \"must rescue\".", "example_in_sentence": "구해야 해요"}, {"type": "grammar", "label": "~게", "exp": "Adverbial suffix forming an adverb from an adjective. 안전하다 → 안전하게 (safely) modifies the verb 구하다.", "example_in_sentence": "안전하게"}]}, {"text": "그래서 매일 열심히 연습해요.", "translation": "That is why they practice hard every day.", "vocab": [{"ko": "매일", "en": "every day"}, {"ko": "열심히", "en": "hard; diligently"}, {"ko": "연습하다", "en": "to practice"}], "analysis": []}, {"text": "힘든 훈련을 통해 실력을 키워요.", "translation": "Through difficult training, they develop their skills.", "vocab": [{"ko": "힘들다", "en": "to be difficult; tough"}, {"ko": "실력", "en": "skill; ability"}, {"ko": "키우다", "en": "to build; to develop"}], "analysis": [{"type": "grammar", "label": "~을/를 통해", "exp": "Instrumental/means particle phrase indicating ''through'' or ''by means of''. 훈련을 통해 (through training).", "example_in_sentence": "훈련을 통해"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object. 실력 (skill) is what is being developed.", "example_in_sentence": "실력을"}]}, {"text": "이런 훈련 덕분에 해양경찰은 바다에서 많은 사람들을 구할 수 있어요.", "translation": "Thanks to such training, the coast guard is able to rescue many people in the sea.", "vocab": [{"ko": "덕분", "en": "thanks to; because of"}, {"ko": "많다", "en": "to be many; much"}], "analysis": [{"type": "expression", "label": "~ 덕분에 (thanks to)", "exp": "a good cause. 훈련 → 훈련 덕분에 = \"thanks to the training\".", "example_in_sentence": "훈련 덕분에"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "ability. 구하다 → 구할 수 있어요 = \"can rescue\".", "example_in_sentence": "구할 수 있어요"}]}, {"text": "우리나라 바다를 더 안전하게 만들고 있어요.", "translation": "They are making our country''s sea even safer.", "vocab": [{"ko": "우리나라", "en": "our country"}, {"ko": "더", "en": "more; even"}], "analysis": [{"type": "grammar", "label": "~게 만들다 (make something ~)", "exp": "brings about a state. 안전하다 → 안전하게 만들다 = \"to make (something) safe\".", "example_in_sentence": "안전하게 만들고"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect indicating an ongoing action. 만들다 → 만들고 있어요 (are making).", "example_in_sentence": "만들고 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "해양경찰", "en": "coast guard", "note": ""}, {"ko": "구조 요원", "en": "rescue personnel", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "훈련", "en": "training", "note": ""}, {"ko": "바다", "en": "sea", "note": ""}, {"ko": "사람", "en": "person; people", "note": ""}, {"ko": "구하다", "en": "to rescue; to save", "note": ""}, {"ko": "훈련장", "en": "training facility", "note": ""}, {"ko": "크다", "en": "to be big; large", "note": ""}, {"ko": "수영장", "en": "swimming pool", "note": ""}, {"ko": "어렵다", "en": "to be difficult", "note": ""}, {"ko": "테스트", "en": "test", "note": ""}, {"ko": "실제", "en": "reality; actual", "note": ""}, {"ko": "비슷하다", "en": "to be similar", "note": ""}, {"ko": "상황", "en": "situation", "note": ""}, {"ko": "만들다", "en": "to make; to create", "note": ""}, {"ko": "물", "en": "water", "note": ""}, {"ko": "빠지다", "en": "to fall (into)", "note": ""}, {"ko": "안전하다", "en": "to be safe", "note": ""}, {"ko": "매일", "en": "every day", "note": ""}, {"ko": "열심히", "en": "hard; diligently", "note": ""}, {"ko": "연습하다", "en": "to practice", "note": ""}, {"ko": "힘들다", "en": "to be difficult; tough", "note": ""}, {"ko": "실력", "en": "skill; ability", "note": ""}, {"ko": "키우다", "en": "to build; to develop", "note": ""}, {"ko": "덕분", "en": "thanks to; because of", "note": ""}, {"ko": "많다", "en": "to be many; much", "note": ""}, {"ko": "우리나라", "en": "our country", "note": ""}, {"ko": "더", "en": "more; even", "note": ""}, {"word": "덕분에", "reading": "deokbuneye", "meaning": "thanks to; owing to", "context": "이런 훈련 덕분에 해양경찰은"}, {"word": "안전하게", "reading": "anjeongha-ge", "meaning": "safely; securely (adverb form of 안전하다)", "context": "우리나라 바다를 더 안전하게 만들고"}]', grammar = '{"patterns": [{"name": "~고 있어요", "level": "Beginner", "exp": "Progressive aspect marker indicating an ongoing action. 받다 (receive) → 받고 있어요 (are receiving).", "ex_ko": "한국 해양경찰의 구조 요원들이 특별한 훈련을 받고 있어요.", "ex_en": "South Korean coast guard rescue personnel are receiving special training."}, {"name": "~을/를", "level": "Beginner", "exp": "Object particle marking the direct object. 훈련 (training) is the object of the verb 받다 (receive).", "ex_ko": "한국 해양경찰의 구조 요원들이 특별한 훈련을 받고 있어요.", "ex_en": "South Korean coast guard rescue personnel are receiving special training."}, {"name": "~는 일 (the work of V-ing)", "level": "Beginner", "exp": "~는 describes 일 (work). 구하다 → 사람을 구하는 일 = \"the work of rescuing people\".", "ex_ko": "이들은 바다에서 사람을 구하는 일을 해요.", "ex_en": "They do the work of rescuing people in the sea."}, {"name": "~에서", "level": "Beginner", "exp": "Locative particle indicating location where an action takes place. 수영장 (swimming pool) is where the test occurs.", "ex_ko": "이들은 바다에서 사람을 구하는 일을 해요.", "ex_en": "They do the work of rescuing people in the sea."}, {"name": "~에는", "level": "Beginner", "exp": "Topic-marking particle ~는 combined with locative ~에. Indicates location with topic emphasis (at the training facility, there is...).", "ex_ko": "훈련장에는 큰 수영장이 있어요.", "ex_en": "There is a large swimming pool at the training facility."}, {"name": "~이/가 있다 (there is)", "level": "Beginner", "exp": "says that something exists. 수영장 → 수영장이 있어요 = \"there is a swimming pool\".", "ex_ko": "훈련장에는 큰 수영장이 있어요.", "ex_en": "There is a large swimming pool at the training facility."}, {"name": "~와/과 비슷한 (similar to)", "level": "Beginner", "exp": "comparison. 바다 → 바다와 비슷한 상황 = \"a situation similar to the sea\".", "ex_ko": "실제 바다와 비슷한 상황을 만들어서 훈련해요.", "ex_en": "They train by creating situations similar to the real sea."}, {"name": "~아/어서 (and then)", "level": "Beginner", "exp": "one action leads to the next. 만들다 → 만들어서 = \"make (situations) and then\".", "ex_ko": "실제 바다와 비슷한 상황을 만들어서 훈련해요.", "ex_en": "They train by creating situations similar to the real sea."}, {"name": "~(으)ㄴ (past verb modifier)", "level": "Beginner", "exp": "describes a noun with a past action. 빠지다 → 물에 빠진 사람 = \"a person who has fallen into the water\".", "ex_ko": "구조 요원들은 물에 빠진 사람을 안전하게 구해야 해요.", "ex_en": "Rescue personnel must safely rescue people who have fallen into the water."}, {"name": "~아/어야 하다 (must)", "level": "Beginner", "exp": "obligation. 구하다 → 구해야 해요 = \"must rescue\".", "ex_ko": "구조 요원들은 물에 빠진 사람을 안전하게 구해야 해요.", "ex_en": "Rescue personnel must safely rescue people who have fallen into the water."}, {"name": "~게", "level": "Beginner", "exp": "Adverbial suffix forming an adverb from an adjective. 안전하다 → 안전하게 (safely) modifies the verb 구하다.", "ex_ko": "구조 요원들은 물에 빠진 사람을 안전하게 구해야 해요.", "ex_en": "Rescue personnel must safely rescue people who have fallen into the water."}, {"name": "~을/를 통해", "level": "Beginner", "exp": "Instrumental/means particle phrase indicating ''through'' or ''by means of''. 훈련을 통해 (through training).", "ex_ko": "힘든 훈련을 통해 실력을 키워요.", "ex_en": "Through difficult training, they develop their skills."}, {"name": "~(으)ㄹ 수 있다 (can)", "level": "Beginner", "exp": "ability. 구하다 → 구할 수 있어요 = \"can rescue\".", "ex_ko": "이런 훈련 덕분에 해양경찰은 바다에서 많은 사람들을 구할 수 있어요.", "ex_en": "Thanks to such training, the coast guard is able to rescue many people in the sea."}, {"name": "~게 만들다 (make something ~)", "level": "Beginner", "exp": "brings about a state. 안전하다 → 안전하게 만들다 = \"to make (something) safe\".", "ex_ko": "우리나라 바다를 더 안전하게 만들고 있어요.", "ex_en": "They are making our country''s sea even safer."}]}', updated_at = now() where article_id = 'mogep2s6jw1k' and md5(translation) = 'f751a65a29ffa09a15b21b2b967df396';
update public.article_cache set translation = '{"texts": ["Recently, Korean office workers have been actively studying artificial intelligence (AI) after work. Their learning speed has been shown to be much faster than at their companies.", "Many office workers are taking AI-related lectures using their personal time. They are learning machine learning, data analysis, and more on online education platforms. They are participating more actively than in education provided by their companies.", "Experts analyzed that this phenomenon is due to changes in the job market. Demand for talent with knowledge of AI technology is increasing. Office workers are studying on their own to prepare for the future.", "However, companies'' adoption of AI is still slow. Many companies are hesitant to introduce new technology. A gap is appearing between office workers'' enthusiasm for learning and the pace of change at companies."], "sentences": [{"text": "최근 한국 직장인들이 퇴근 후 인공지능(AI) 공부에 열심히 참여하고 있어요.", "translation": "Recently, Korean office workers are actively participating in artificial intelligence studies after work.", "vocab": [{"ko": "퇴근", "en": "leaving work"}, {"ko": "인공지능", "en": "artificial intelligence"}, {"ko": "참여하다", "en": "to participate"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker showing ongoing action. Combines 고 (connective) + 있다 (auxiliary) + 어요 (polite ending). Indicates current state or repeated action.", "example_in_sentence": "참여하고 있어요"}]}, {"text": "이들의 학습 속도는 회사보다 훨씬 빠른 것으로 나타났습니다.", "translation": "Their pace of learning turned out to be much faster than that of their companies.", "vocab": [{"ko": "속도", "en": "speed"}, {"ko": "훨씬", "en": "much; far"}, {"ko": "빠르다", "en": "to be fast"}, {"ko": "나타나다", "en": "to appear; to be shown"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ 것으로 나타나다", "exp": "Passive construction meaning ''it was revealed/shown that''. Nominalizes a clause with ~ㄴ 것 and combines with 나타나다in past tense.", "example_in_sentence": "빠른 것으로 나타났습니다"}]}, {"text": "많은 직장인들이 개인 시간을 활용해 AI 관련 강의를 듣고 있어요.", "translation": "Many office workers are using their personal time to take AI-related lectures.", "vocab": [{"ko": "활용하다", "en": "to utilize"}, {"ko": "관련", "en": "related"}, {"ko": "강의", "en": "lecture"}], "analysis": [{"type": "grammar", "label": "~아/어 (connective)", "exp": "Sequential or causal connection showing means/method. Connects two actions where the first enables the second.", "example_in_sentence": "활용해"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect. Indicates ongoing state of listening.", "example_in_sentence": "듣고 있어요"}]}, {"text": "온라인 교육 플랫폼에서 머신러닝, 데이터 분석 등을 배우고 있습니다.", "translation": "They are learning machine learning, data analysis, and more on online educational platforms.", "vocab": [{"ko": "플랫폼", "en": "platform"}, {"ko": "머신러닝", "en": "machine learning"}, {"ko": "데이터 분석", "en": "data analysis"}], "analysis": [{"type": "grammar", "label": "~고 있습니다", "exp": "Progressive aspect in formal register. Same function as ~고 있어요 but with formal polite ending ~습니다.", "example_in_sentence": "배우고 있습니다"}]}, {"text": "회사에서 제공하는 교육보다 더 적극적으로 참여하고 있어요.", "translation": "They are participating more actively than in the training their companies provide.", "vocab": [{"ko": "제공하다", "en": "to provide"}, {"ko": "적극적", "en": "active; proactive"}], "analysis": [{"type": "grammar", "label": "~는 (relative clause modifier)", "exp": "Present tense relative clause modifying the following noun. ~는 converts verb to attributive form describing the noun that follows.", "example_in_sentence": "제공하는 교육"}]}, {"text": "전문가들은 이런 현상이 취업 시장의 변화 때문이라고 분석했어요.", "translation": "Experts analyzed that this phenomenon was due to changes in the job market.", "vocab": [{"ko": "전문가", "en": "expert"}, {"ko": "현상", "en": "phenomenon"}, {"ko": "취업", "en": "employment; getting a job"}, {"ko": "변화", "en": "change"}], "analysis": [{"type": "grammar", "label": "~때문이다", "exp": "Causal expression meaning ''because of; due to''. Follows noun (with 의 if needed) to indicate reason/cause.", "example_in_sentence": "취업 시장의 변화 때문이라고"}, {"type": "grammar", "label": "~라고 분석하다", "exp": "Quotative particle ~라고 with verb of saying/analysis. Reports indirect speech or analysis results.", "example_in_sentence": "때문이라고 분석했어요"}]}, {"text": "AI 기술을 아는 인재에 대한 수요가 늘어나고 있습니다.", "translation": "Demand for talent that understands AI technology is increasing.", "vocab": [{"ko": "기술", "en": "technology"}, {"ko": "인재", "en": "talented person; talent"}, {"ko": "수요", "en": "demand"}, {"ko": "늘어나다", "en": "to increase"}], "analysis": [{"type": "grammar", "label": "~는 (relative clause modifier)", "exp": "Present tense relative clause. ~는 modifies 인재 to describe people who understand AI technology.", "example_in_sentence": "아는 인재"}, {"type": "grammar", "label": "~고 있습니다", "exp": "Progressive aspect in formal register indicating ongoing increase.", "example_in_sentence": "늘어나고 있습니다"}]}, {"text": "직장인들은 미래를 준비하기 위해 스스로 공부하고 있어요.", "translation": "Office workers are studying by themselves in order to prepare for the future.", "vocab": [{"ko": "준비하다", "en": "to prepare"}, {"ko": "스스로", "en": "by oneself; on one''s own"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Purpose/intention marker. Follows verb stem to indicate goal or objective of the main action.", "example_in_sentence": "준비하기 위해"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect indicating ongoing self-study.", "example_in_sentence": "공부하고 있어요"}]}, {"text": "하지만 회사들의 AI 도입은 아직 느린 편이에요.", "translation": "However, companies are still rather slow to adopt AI.", "vocab": [{"ko": "도입", "en": "adoption; introduction"}, {"ko": "아직", "en": "still; yet"}, {"ko": "느리다", "en": "to be slow"}], "analysis": [{"type": "expression", "label": "~ㄴ/은 편이다", "exp": "Expression indicating tendency or general characteristic. Suggests ''tends to be; is on the side of being''.", "example_in_sentence": "느린 편이에요"}]}, {"text": "많은 기업들이 새로운 기술 도입을 망설이고 있습니다.", "translation": "Many companies are hesitating to adopt new technology.", "vocab": [{"ko": "기업", "en": "company; enterprise"}, {"ko": "새롭다", "en": "to be new"}, {"ko": "망설이다", "en": "to hesitate"}], "analysis": [{"type": "grammar", "label": "~고 있습니다", "exp": "Progressive aspect in formal register. Indicates ongoing state of hesitation.", "example_in_sentence": "망설이고 있습니다"}]}, {"text": "직장인들의 학습 열정과 회사의 변화 속도 사이에 차이가 나타나고 있어요.", "translation": "A gap is emerging between office workers'' enthusiasm for learning and the pace of change at companies.", "vocab": [{"ko": "열정", "en": "enthusiasm; passion"}, {"ko": "속도", "en": "speed; pace"}, {"ko": "차이", "en": "difference; gap"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect indicating an emerging or developing gap.", "example_in_sentence": "나타나고 있어요"}]}], "version": "s6"}', vocab = '[{"ko": "퇴근", "en": "leaving work", "note": ""}, {"ko": "인공지능", "en": "artificial intelligence", "note": ""}, {"ko": "참여하다", "en": "to participate", "note": ""}, {"ko": "속도", "en": "speed", "note": ""}, {"ko": "훨씬", "en": "much; far", "note": ""}, {"ko": "빠르다", "en": "to be fast", "note": ""}, {"ko": "나타나다", "en": "to appear; to be shown", "note": ""}, {"ko": "활용하다", "en": "to utilize", "note": ""}, {"ko": "관련", "en": "related", "note": ""}, {"ko": "강의", "en": "lecture", "note": ""}, {"ko": "플랫폼", "en": "platform", "note": ""}, {"ko": "머신러닝", "en": "machine learning", "note": ""}, {"ko": "데이터 분석", "en": "data analysis", "note": ""}, {"ko": "제공하다", "en": "to provide", "note": ""}, {"ko": "적극적", "en": "active; proactive", "note": ""}, {"ko": "전문가", "en": "expert", "note": ""}, {"ko": "현상", "en": "phenomenon", "note": ""}, {"ko": "취업", "en": "employment; getting a job", "note": ""}, {"ko": "변화", "en": "change", "note": ""}, {"ko": "기술", "en": "technology", "note": ""}, {"ko": "인재", "en": "talented person; talent", "note": ""}, {"ko": "수요", "en": "demand", 